package com.earthtrip.notification.adapter.in.web.api.v1.me.notifications;import com.earthtrip.notification.application.port.in.NotificationUseCase;import com.earthtrip.sharedkernel.security.CurrentActor;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/me/notifications") class NotificationsController{private final NotificationUseCase useCase;private final CurrentActor actor;NotificationsController(NotificationUseCase u,CurrentActor a){useCase=u;actor=a;}@GetMapping List<NotificationUseCase.NotificationResult>get(@RequestParam(defaultValue="false")boolean unreadOnly){return useCase.list(actor.requireUserId(),unreadOnly);}}
